//! Task Scheduler (`/api/v1/scheduler/...`).
//!
//! Configuration key `scheduler` ([`SchedulerConfig`]): every task becomes persistent systemd
//! units generated by rynasd (`/etc/systemd/system/rynas-task-<id>.service` and, with a
//! trigger, `.timer`). Writes stage pending changes; `POST /api/v1/config/apply` applies them.
//! Each run is recorded with its result and the tail of its output (journal).

use serde::{Deserialize, Serialize};

use crate::PendingOp;

fn default_true() -> bool {
    true
}

/// The `scheduler` configuration key.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SchedulerConfig {
    #[serde(default)]
    pub tasks: Vec<ScheduledTask>,
}

/// One scheduled task.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ScheduledTask {
    /// `[a-z0-9][a-z0-9-]{0,47}`, unique; the units are `rynas-task-<id>.*`. Cannot change.
    pub id: String,
    /// Display name.
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub description: String,
    /// A disabled task keeps its units but its timer is stopped (run now still works).
    #[serde(default = "default_true")]
    pub enabled: bool,
    pub action: TaskAction,
    pub trigger: TaskTrigger,
    /// `RuntimeMaxSec`: the run is stopped (whole cgroup) after this many seconds.
    #[serde(default)]
    pub timeout_s: Option<u64>,
    /// `Nice=` (-20..=19); `None`: 10 for user tasks, 0 for internal ones.
    #[serde(default)]
    pub nice: Option<i32>,
    /// `IOWeight=` (1..=10000); `None`: systemd's default (100).
    #[serde(default)]
    pub io_weight: Option<u32>,
    #[serde(default)]
    pub notify: NotifyPolicy,
    /// Attach the output (last 256 KiB) to the notification.
    #[serde(default)]
    pub notify_output: bool,
}

/// What a task runs. User actions (`command`, `script`) run as `user`; internal actions run
/// as a rynasd task (UPID, task panel) started by `rynasctl job run <id>`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum TaskAction {
    /// A shell command line (`/bin/sh`).
    Command {
        command: String,
        /// `root` (administrators only) or a local user (uid 1000..=59999).
        #[serde(default = "default_root")]
        user: String,
    },
    /// A script stored by rynas (`/var/lib/rynas/tasks/<id>/run`, root:root 0700); the
    /// interpreter comes from its `#!` line (default `/bin/sh`). It reads the script on its
    /// standard input, so the script itself gets none.
    Script {
        script: String,
        #[serde(default = "default_root")]
        user: String,
    },
    /// Snapshot job (`/api/v1/snapshots/jobs`): `btrbk run` with the job's configuration.
    Snapshot { job: String },
    /// Replica target with its own schedule (`/api/v1/snapshots/replication`): btrbk sends
    /// the job's missing snapshots to the target and applies the target's retention.
    Replicate { job: String, target: String },
    /// `btrfs scrub` of the filesystem mounted at `filesystem`.
    Scrub { filesystem: String },
    /// SMART self-test of a disk (`sda`, `nvme0n1`).
    SmartTest {
        disk: String,
        #[serde(default)]
        test: SmartTestKind,
    },
    /// `#recycle` cleanup of one share, or of every share with a recycle bin.
    RecycleCleanup {
        #[serde(default)]
        share: Option<String>,
        /// Override of the share's retention.
        #[serde(default)]
        days: Option<u32>,
    },
    /// Scheduled shutdown of a power schedule rule (`/api/v1/power/schedule`): checks, then
    /// a clean poweroff. Runs `rynasctl power scheduled-shutdown <rule>`; created, changed
    /// and removed with its rule.
    PowerShutdown { rule: String },
    /// Backup job (`/api/v1/backup/restic/jobs`): backup, retention and maintenance of its
    /// repository by `rynas-backup-worker`; created, changed and removed with its job.
    Backup { job: String },
}

fn default_root() -> String {
    "root".into()
}

impl TaskAction {
    /// Internal actions run inside rynasd; their command cannot be edited.
    pub fn is_internal(&self) -> bool {
        !matches!(self, TaskAction::Command { .. } | TaskAction::Script { .. })
    }

    /// The user a user action runs as.
    pub fn user(&self) -> Option<&str> {
        match self {
            TaskAction::Command { user, .. } | TaskAction::Script { user, .. } => Some(user),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum SmartTestKind {
    #[default]
    Short,
    Long,
}

/// When a task runs.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum TaskTrigger {
    /// systemd calendar event (`OnCalendar=`), e.g. `hourly`, `Mon..Fri 02:30`. A request may
    /// give `cron` instead (`0 4 * * *`): it is converted and stored as `on_calendar`.
    Calendar {
        #[serde(default)]
        on_calendar: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        cron: Option<String>,
        /// `Persistent=`: a run missed while the NAS was off happens at the next boot.
        #[serde(default = "default_true")]
        persistent: bool,
        /// `RandomizedDelaySec=`.
        #[serde(default)]
        randomized_delay_s: u32,
    },
    /// After every boot (`OnBootSec=`), `delay_s` seconds after systemd started.
    Boot {
        #[serde(default = "default_boot_delay")]
        delay_s: u32,
    },
    /// No timer: run now only.
    Manual,
}

fn default_boot_delay() -> u32 {
    60
}

/// When a finished run sends a notification.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum NotifyPolicy {
    Never,
    #[default]
    OnFailure,
    Always,
}

/// `GET /api/v1/scheduler/tasks[/{id}]`: a task as the session user sees it (its staged
/// version if any) with the system state.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct TaskView {
    pub task: ScheduledTask,
    pub status: TaskStatus,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct TaskStatus {
    /// What the user's pending changeset does to this task.
    #[serde(default)]
    pub pending: Option<PendingOp>,
    /// The task is in the applied configuration (its units exist).
    pub applied: bool,
    /// `rynas-task-<id>.service`.
    pub unit: String,
    /// The service is running now.
    pub running: bool,
    /// Next start of the timer.
    #[serde(default)]
    pub next_run_ms: Option<u64>,
    /// Latest recorded run.
    #[serde(default)]
    pub last_run: Option<TaskRun>,
}

/// One recorded run (from the `ExecStopPost` hook).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct TaskRun {
    /// Increasing id of the record.
    pub id: u64,
    pub task_id: String,
    /// systemd invocation id of the run.
    pub invocation_id: String,
    #[serde(default)]
    pub start_ms: Option<u64>,
    pub end_ms: u64,
    /// systemd's `$SERVICE_RESULT`: `success`, `exit-code`, `signal`, `timeout`, `core-dump`...
    pub result: String,
    /// Exit status of the main process (`None` when it was killed by a signal).
    #[serde(default)]
    pub exit_code: Option<i32>,
    /// Signal name when it was killed (`TERM`, `KILL`).
    #[serde(default)]
    pub signal: Option<String>,
    pub ok: bool,
    /// Bytes of output kept (the last 256 KiB).
    pub output_bytes: u64,
    /// The output was longer than what is kept.
    pub output_truncated: bool,
    /// The output itself: only in `GET .../history/{n}`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub output: Option<String>,
}

/// `POST /api/v1/scheduler/tasks/preview-calendar`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CalendarPreviewRequest {
    pub expression: String,
    #[serde(default)]
    pub syntax: CalendarSyntax,
    /// Number of next runs to compute (default 5, at most 20).
    #[serde(default)]
    pub count: Option<u32>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum CalendarSyntax {
    /// systemd `OnCalendar=`.
    #[default]
    Calendar,
    /// Five-field crontab line (`m h dom mon dow`) or `@daily`-style shortcut.
    Cron,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct CalendarPreview {
    pub valid: bool,
    /// The `OnCalendar=` expression to store (converted from cron if needed).
    #[serde(default)]
    pub on_calendar: String,
    /// systemd's normalized form.
    #[serde(default)]
    pub normalized: String,
    /// Next runs.
    #[serde(default)]
    pub next_ms: Vec<u64>,
    #[serde(default)]
    pub error: Option<String>,
}

/// `GET /api/v1/scheduler/system-timers`: systemd timers not generated by rynas (read-only).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SystemTimer {
    pub unit: String,
    pub activates: String,
    #[serde(default)]
    pub next_ms: Option<u64>,
    #[serde(default)]
    pub last_ms: Option<u64>,
    /// `OnCalendar=` expressions of the timer, if any.
    #[serde(default)]
    pub on_calendar: Vec<String>,
}

/// `GET /api/v1/scheduler/cron-entries`: crontab lines found on the system (read-only).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct CronEntry {
    /// `/etc/crontab`, `/etc/cron.d/<name>` or `/var/spool/cron/crontabs/<user>`.
    pub source: String,
    pub line: u32,
    /// The five time fields or the `@` shortcut.
    pub schedule: String,
    pub user: String,
    pub command: String,
    /// The equivalent trigger, when there is one (`@reboot` is a boot trigger).
    #[serde(default)]
    pub trigger: Option<TaskTrigger>,
}
